from pathlib import Path
from xml.sax.saxutils import escape
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, PageBreak, KeepTogether
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib import colors
out=Path('C:/AI-BS/output/pdf/Stehouwer_Publishing_Website_Review_2026-11-14.pdf')
s=getSampleStyleSheet()
s.add(ParagraphStyle(name='TitleX',fontName='Helvetica-Bold',fontSize=23,leading=28,textColor=colors.HexColor('#15394e'),spaceAfter=15))
s.add(ParagraphStyle(name='HeadX',fontName='Helvetica-Bold',fontSize=13,leading=17,textColor=colors.HexColor('#15394e'),spaceBefore=12,spaceAfter=7))
s.add(ParagraphStyle(name='BodyX',fontName='Helvetica',fontSize=10.5,leading=15,spaceAfter=9))
s.add(ParagraphStyle(name='SmallX',fontName='Helvetica',fontSize=9,leading=13,spaceAfter=8,textColor=colors.HexColor('#526875')))
story=[]
def p(t,style='BodyX'):story.append(Paragraph(t,s[style]))
def title(t):p(t,'TitleX')
def head(t):p(t,'HeadX')
def link(label,path):return '<link href="https://stehouwer-publishing.com'+path+'" color="#17646b"><u>'+label+'</u></link>'
def item(h,f,r,links=''):
 parts=[Paragraph(h,s['HeadX']),Paragraph('<b>Finding:</b> '+f,s['BodyX']),Paragraph('<b>Recommended improvement:</b> '+r,s['BodyX'])]
 if links:parts.append(Paragraph(links,s['SmallX']))
 story.append(KeepTogether(parts))
title('Stehouwer Publishing\nWebsite Review'.replace('\n','<br/>'))
p('Public content and technical inspection | November 14, 2026','SmallX')
p(link('stehouwer-publishing.com','/'))
head('Purpose and scope')
p('This report organizes the supplied inspection into a reference for planning website improvements. The inspection covered all seven main pages, page metadata, robots.txt, the sitemap, and selected downloads. No website changes were made during that inspection.')
p('The findings below are preserved from the supplied November 14, 2026 review. They have not been independently retested for this PDF. A finding may need to be rechecked before work begins.')
head('Recommended order of work')
p('<b>1. Repair essential functions and search metadata.</b> Restore PDF downloads, connect the manuscript inquiry link, correct page metadata, and fix the social-sharing image.')
p('<b>2. Clarify pricing and visitor navigation.</b> Explain package costs and commitments, and give homepage visitors clear routes to books, publishing services, marketing services, and film work.')
p('<b>3. Strengthen book and film presentation.</b> Add dedicated book pages, useful samples, approved creative assets, and supporting project information.')
head('Priority overview')
p('<b>High priority:</b> broken PDF samples; duplicated canonical URLs and metadata; broken social-sharing image; manuscript inquiry without a destination.')
p('<b>Medium priority:</b> robots.txt and sitemap issues; missing-page responses; public display of local broadcast configuration and a stream-key value.')
head('Use this report as a work list')
p('Pages 2-3 explain the technical findings and recommended fixes. Pages 4-5 cover content, pricing, customer trust, and the checks still needed before treating the review as a complete usability or performance audit.')
story.append(PageBreak())
title('High-Priority Fixes')
item('1. Restore the free PDF samples','Both “Download Free PDF Sample” links return the website\'s HTML rather than PDF files.','Restore the actual samples and verify that each opens as a PDF. These links are important steps toward book purchases.',link('Library','/library'))
item('2. Give each page its own metadata','All seven main pages declare the homepage as their canonical URL and share the same title and description.','Give each page its own canonical URL, descriptive title, description, and social metadata. This removes conflicting signals about which pages should appear in search.',link('Example: Authors','/authors'))
item('3. Correct the social-sharing image','The social-sharing image /images/hero-bg.jpg returns HTML. The differently named /images/hero_bg.jpg exists.','Use a verified image URL and test Facebook and other social previews.',link('Affected image','/images/hero-bg.jpg')+' | '+link('Differently named image','/images/hero_bg.jpg'))
item('4. Connect the manuscript inquiry','“Submit Manuscript Inquiry” is an anchor without an href, so it has no linked destination.','Connect it to an accessible inquiry form or email destination, then test keyboard and mobile use.',link('Library','/library'))
story.append(PageBreak())
title('Medium-Priority Fixes')
item('5. Clean up crawler and sitemap files','robots.txt contains the application\'s HTML after Cloudflare\'s crawler rules. The sitemap contains only the homepage.','Serve a clean robots.txt and list the intended public pages in the sitemap. Preserve intentional crawler preferences.',link('robots.txt','/robots.txt')+' | '+link('Sitemap','/sitemap.xml'))
item('6. Return proper missing-page responses','A deliberately nonexistent URL returns HTTP 200 with the application shell.','Add proper missing-page handling and HTTP 404 responses while preserving valid application routes.')
item('7. Separate public broadcasts from studio controls','The public broadcast page displays local ingest configuration and a stream-key value while the stream is offline.','Move studio configuration into private controls. Show visitors a schedule, previous broadcasts, and a useful offline message. Review whether the displayed key is operational.',link('Live broadcasts','/live'))
head('Implementation boundary')
p('This document is a planning reference. It does not indicate that any fix, configuration change, website deployment, or stream-key review has been completed.')
story.append(PageBreak())
title('Content and Sales Improvements')
head('Give the homepage clearer visitor paths')
p('Publishing, advertising, film production, and AI tools currently compete for attention. Present clear choices such as “Browse Books,” “Publishing Services,” “Marketing Services,” and “Film Portfolio.” Give the AI offer a dedicated page with examples and fuller details before checkout. '+link('Homepage','/'))
head('Clarify publishing prices')
p('Three services at $750 total $2,250, while the full package starts at $3,000. Explain the additional package benefits. Clarify the shift between “manuscripts” and “scripts” and exactly how the additional 5% fee works. '+link('Library','/library'))
head('Make advertising commitments easier to evaluate')
p('State whether ad spend is included, what clients receive each month, and what happens after 90 days. Tier 1\'s stated fees imply a <b>$5,250 initial three-month commitment</b>; showing that total would improve transparency. Support “proven results” claims with approved case studies. '+link('Marketing','/marketing'))
head('Show more of the creative work')
p('The film page largely lists credits. Add approved posters, trailers, stills, project descriptions, and links supporting awards and credits. '+link('Film &amp; Television','/film-tv'))
head('Create dedicated book pages')
p('Give each title a synopsis, excerpt, author information, available formats, and a clear purchase link. Separate buying books from purchasing publishing services.')
head('Make contact and trust information easier to find')
p('Add a prominent Contact link, clickable telephone number, inquiry categories, and visible privacy information for forms. Explain AI pass duration, usage limits, availability, and support before purchase.')
story.append(PageBreak())
title('Checks Still Needed')
p('This was a public content and technical inspection. The following areas remain <b>unverified</b>:')
for h,t in [('Mobile layout','Check navigation, readable text, page flow, and controls on phone-sized screens.'),('Keyboard behavior','Check that links, navigation, forms, and other controls can be reached and used with a keyboard.'),('Measured color contrast','Measure text and interface contrast rather than judging it only by appearance.'),('Core Web Vitals','Measure real page performance; this report does not establish performance scores.'),('Form delivery','Confirm that inquiries submit successfully and reach their intended destination.'),('Checkout completion','Test the purchase flow through completion under an appropriate authorized test process.'),('Actual search indexing','Check indexing evidence; metadata inspection alone does not establish which pages appear in search.')]:
 head(h);p(t)
head('Audit limitation')
p('These checks are needed before calling this a complete usability or performance audit. The supplied review did not confirm them, and creation of this PDF does not change their status.')
def footer(c,d):
 c.setStrokeColor(colors.HexColor('#c6d6de'));c.line(42,38,570,38)
 c.setFillColor(colors.HexColor('#526875'));c.setFont('Helvetica',8);c.drawString(42,25,'Stehouwer Publishing | Supplied inspection: November 14, 2026');c.drawRightString(570,25,str(d.page))
SimpleDocTemplate(str(out),pagesize=(612,792),leftMargin=42,rightMargin=42,topMargin=42,bottomMargin=50,title='Stehouwer Publishing Website Review - November 14, 2026').build(story,onFirstPage=footer,onLaterPages=footer)
print(out)
